/** subscriptions.billing_method (0028_k8.sql, default 'kartya'). */
export const BILLING_METHODS = ['kartya', 'atutalas'] as const;
export type BillingMethod = (typeof BILLING_METHODS)[number];
export const BILLING_METHOD_LABELS: Record<BillingMethod, string> = { kartya: 'kártya', atutalas: 'átutalás' };

/**
 * system_state['kapcsolok.fizetes'], merged over these defaults (unknown keys / wrong types ignored).
 *  - atutalas: the client may choose bank transfer. Default: ON when APP_ENV=demo, OFF in production until the ÁSZF
 *    (lawyer) knows the transfer, the díjbekérő, the 8 days and the late handling. OFF never drops a client who already
 *    pays by transfer: his díjbekérők keep coming.
 *  - kesesLeallit: a transfer 8 days late locks the service (reason 'atutalas_kesik'). Default OFF (owner decision open):
 *    late transfers only get reminders (day 1, 4, 8 after the due day) and the red "késik" in the console.
 *  - kozlemeny: 'havi' = the transfer memo is the díjbekérő's own order number (ADZ-10482-2026-12; Autokassza matches the
 *    memo against invoice / díjbekérő / order numbers), 'allando' = one fixed memo for a standing order (ADZ-10482; only
 *    if the Autokassza test shows that it pairs by amount + sender account). Owner question, see B_jegyzet.
 */
export interface FizetesKapcsolok {
  atutalas: boolean;
  kesesLeallit: boolean;
  kozlemeny: 'havi' | 'allando';
}
export const FIZETES_KAPCSOLOK_KEY = 'kapcsolok.fizetes';
export function fizetesKapcsolokDefault(appEnv: string): FizetesKapcsolok {
  return { atutalas: appEnv === 'demo', kesesLeallit: false, kozlemeny: 'havi' };
}

