/**
 * The order number of a díjbekérő, unique per month (the Számlázz.hu "Rendelésszám ismétlődés tiltása" is ON):
 * ADZ-<ügyfélszám>-<ÉÉÉÉ>-<HH> (HH = the first month of the period), a re-issue gets -2, -3 … at the end.
 */
export function orderNoOf(customerNo: number, periodStart: _ISODate, n = 1): string {
  const base = `${TRANSFER_RULES.orderPrefix}${customerNo}-${periodStart.slice(0, 4)}-${periodStart.slice(5, 7)}`;
  return n > 1 ? `${base}-${n}` : base;
}
/** The memo the client writes on the transfer (one place to change the format – owner question). */
export function kozlemenyOf(customerNo: number, orderNo: string, mode: FizetesKapcsolok['kozlemeny']): string {
  return mode === 'allando' ? `${TRANSFER_RULES.orderPrefix}${customerNo}` : orderNo;
}

